function calculateCoherence(state) {
  const acts = Object.values(state).filter(v => v && v.activation).map(v => v.activation);
  if (!acts.length) return 0;
  const mean = acts.reduce((a,b) => a+b, 0) / acts.length;
  const variance = acts.reduce((sum, a) => sum + (a-mean)**2, 0) / acts.length;
  return Math.max(0, 1 - variance * 4);
}